application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&family=Space+Grotesk:wght@500;700&display=swap');

:root { --ink:#17212b; --muted:#71808d; --line:#e4e9ed; --cream:#f7f8f5; --blue:#3468f5; --blue-soft:#eef3ff; --coral:#ff806d; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; color:var(--ink); background:linear-gradient(135deg,#f5f8ff 0%,#fffaf5 100%); font-family:'DM Sans',sans-serif; }
body:before { content:""; position:fixed; width:360px; height:360px; border-radius:50%; background:#e6efff; top:-150px; right:-100px; z-index:-1; }
.app-shell { width:min(900px,calc(100% - 32px)); margin:0 auto; padding:58px 0 70px; }
.hero { text-align:center; margin-bottom:34px; }
.eyebrow { color:var(--blue); font-size:11px; font-weight:700; letter-spacing:2px; margin-bottom:15px; }
h1 { font-family:'Space Grotesk',sans-serif; font-size:clamp(34px,6vw,54px); letter-spacing:-2px; line-height:1; margin:0 0 14px; }
.hero p { color:var(--muted); font-size:16px; margin:0; }
.quiz-card { background:white; border:1px solid var(--line); border-radius:24px; padding:10px 30px 30px; box-shadow:0 18px 55px rgba(47,73,116,.08); }
.question { display:flex; gap:22px; padding:28px 0; border-bottom:1px solid var(--line); }
.question-number { flex:none; display:grid; place-items:center; width:38px; height:38px; border-radius:12px; background:var(--blue-soft); color:var(--blue); font-weight:700; font-size:13px; }
.question-content { flex:1; }
h2 { font-size:19px; margin:7px 0 19px; font-weight:700; }
.options { display:flex; flex-wrap:wrap; gap:10px; }
.option { position:relative; display:flex; align-items:center; gap:10px; min-height:44px; padding:10px 16px; border:1px solid var(--line); border-radius:12px; color:#52616e; cursor:pointer; transition:.2s ease; font-size:14px; }
.option:hover { border-color:#9eb5ff; background:#fafbff; }
.option input { position:absolute; opacity:0; pointer-events:none; }
.radio-mark { width:16px; height:16px; border:2px solid #bdc8d2; border-radius:50%; transition:.2s; }
.option:has(input:checked) { border-color:var(--blue); background:var(--blue-soft); color:var(--blue); font-weight:700; }
.option:has(input:checked) .radio-mark { border:5px solid var(--blue); }
.actions { display:flex; align-items:center; gap:18px; padding-top:28px; }
button { border:0; border-radius:12px; padding:14px 22px; color:white; background:var(--blue); font:700 15px 'DM Sans',sans-serif; cursor:pointer; box-shadow:0 8px 18px rgba(52,104,245,.24); transition:transform .2s,background .2s; }
button:hover { background:#2454db; transform:translateY(-2px); }
button span { font-size:20px; margin-left:8px; vertical-align:-1px; }
.message { color:var(--coral); font-size:13px; margin:0; }
.result { margin:25px auto 0; width:min(360px,100%); text-align:center; border-radius:20px; padding:22px; background:var(--ink); color:white; }
.result-label { color:#aebbc7; font-size:10px; letter-spacing:2px; font-weight:700; }
.score { color:#ffb36c; font:700 45px 'Space Grotesk',sans-serif; line-height:1.1; margin:5px 0; }
.result p { color:#c4cdd4; font-size:13px; margin:0; }
@media (max-width:600px) { .app-shell { padding-top:38px; } .quiz-card { padding:5px 18px 22px; } .question { gap:13px; } .options { display:grid; } .option { width:100%; } .actions { display:block; } button { width:100%; } .message { margin-top:12px; text-align:center; } }

application.javascript:
document.addEventListener('DOMContentLoaded', function () {
  const form = document.getElementById('quiz-form');
  const scoreElement = document.querySelector('[data-testid="quiz-score"]');
  const message = document.getElementById('message');
  const resultText = document.getElementById('result-text');
  const answers = ['Mars', 'Pacific', 'Six'];

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    const selections = answers.map(function (_, index) {
      const selected = form.querySelector('input[name="q' + (index + 1) + '"]:checked');
      return selected ? selected.value : null;
    });

    if (selections.some(function (value) { return value === null; })) {
      message.textContent = 'Please answer all three questions first.';
      scoreElement.removeAttribute('data-score');
      scoreElement.textContent = '—';
      resultText.textContent = 'Complete the quiz to reveal your result.';
      return;
    }

    const score = selections.reduce(function (total, answer, index) {
      return total + (answer === answers[index] ? 1 : 0);
    }, 0);
    scoreElement.textContent = score + ' / 3';
    scoreElement.setAttribute('data-score', String(score));
    message.textContent = '';
    resultText.textContent = score === 3 ? 'Perfect score. Brilliant work!' : score === 0 ? 'A fresh try is always worthwhile.' : 'Nice work — keep exploring!';
  });
});
